#!/usr/bin/env bash
# recipes/crate-normalize-line-endings--0-3-0/build.sh -- stage the normalize-line-endings 0.3.0 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/normalize-line-endings-0.3.0"
mkdir -p "${dest}"
cp -R "${CVC_SOURCE_DIR}/." "${dest}/"
# cargo reads a directory-source entry's checksums from here. "package" is the
# Cargo.lock checksum, which cargo compares; no per-file hashes (the bundle's
# own sha256 covers the files).
printf '{"files":{},"package":"61807f77802ff30975e01f4f071c8ba10c022052f98b3294119f3e615d13e5be"}\n' > "${dest}/.cargo-checksum.json"
